import {McpServer} from '@modelcontextprotocol/server';import {serveStdio} from '@modelcontextprotocol/server/stdio';import {z} from 'zod/v4';import {PageDriver} from '../../dist/actions/page-driver.js';
let active=0,cancelled=0;const driver=new PageDriver({});driver.observe=async()=>({phase:'contest_running',identity:{team_name:'synthetic'}});
serveStdio(()=>{const s=new McpServer({name:'cancel-test',version:'1'});s.registerTool('wait',{inputSchema:z.object({})},async(_,ctx)=>{active++;try{await driver.waitForChange(5000,ctx.mcpReq.signal);return {content:[{type:'text',text:'timeout'}]};}catch(e){if(ctx.mcpReq.signal.aborted)cancelled++;return {content:[{type:'text',text:'cancelled'}],isError:true};}finally{active--;}});s.registerTool('status',{inputSchema:z.object({})},async()=>({content:[{type:'text',text:JSON.stringify({active,cancelled})}]}));return s;});
